class Solution {
public:
    int createSortedArray(vector<int>& instructions) {
        const int MOD = 1e9 + 7;
        const int MAXV = 100002;
        vector<int> bit(MAXV, 0);

        auto update = [&](int i, int val) {
            for (; i < MAXV; i += i & (-i))
                bit[i] += val;
        };

        auto query = [&](int i) -> long long {
            long long sum = 0;
            for (; i > 0; i -= i & (-i))
                sum += bit[i];
            return sum;
        };

        long long totalCost = 0;
        long long inserted = 0;

        for (int x : instructions) {
            long long less = query(x - 1);
            long long greater = inserted - query(x);
            totalCost += min(less, greater);
            update(x, 1);
            inserted++;
        }

        return (int)(totalCost % MOD);
    }
};
